function artifact(string $name): ?array {
    $path=envv('MODEL_ARTIFACT_DIR',dirname(__DIR__).'/service/artifacts').'/'.$name;
    if(!is_file($path)||filesize($path)>5000000) return null;
    try { return json_decode(file_get_contents($path),true,64,JSON_THROW_ON_ERROR); } catch(Throwable $e) { return null; }
}
function metric(mixed $value): string { return is_numeric($value)?number_format((float)$value,3):'—'; }
